package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MathUtils_lcm_TriageGen1Test {

    @Test
    public void testLcmWithZero() {
        // Coverage for: if (a==0 || b==0)
        assertEquals(0, MathUtils.lcm(0, 10));
        assertEquals(0, MathUtils.lcm(10, 0));
        assertEquals(0, MathUtils.lcm(0, 0));
    }

    @Test
    public void testLcmPositiveNumbers() {
        // Standard cases
        assertEquals(12, MathUtils.lcm(4, 6));
        assertEquals(15, MathUtils.lcm(3, 5));
        assertEquals(7, MathUtils.lcm(7, 7));
        assertEquals(1, MathUtils.lcm(1, 1));
    }

    @Test
    public void testLcmWithNegativeNumbers() {
        // Coverage for: Math.abs(...)
        // lcm(a, b) is typically defined as positive
        assertEquals(12, MathUtils.lcm(-4, 6));
        assertEquals(12, MathUtils.lcm(4, -6));
        assertEquals(12, MathUtils.lcm(-4, -6));
    }

    @Test
    public void testLcmOverflow() {
        // Coverage for: if (lcm == Integer.MIN_VALUE) { throw new ArithmeticException(...) }
        // We need to find inputs where (a + gcd(a,b)) * b results in a value that overflows to Integer.MIN_VALUE
        // Or more simply, an overflow that triggers the specific exception check.
        // Example: Large prime numbers or values close to Integer.MAX_VALUE.

        // If we assume mulAndCheck throws or returns MIN_VALUE on specific overflow patterns:
        // Note: The logic in the provided code is slightly unusual: lcm = Math.abs(mulAndCheck(a + gcd(a, b), b))
        // To trigger lcm == Integer.MIN_VALUE, mulAndCheck must return Integer.MIN_VALUE (since Math.abs(MIN_VALUE) is still MIN_VALUE).

        // Let's try to find a case where mulAndCheck results in Integer.MIN_VALUE.
        // Since we don't have the implementation of mulAndCheck, we assume it handles overflow.
        // A common way to get MIN_VALUE is overflow from MAX_VALUE.

        // Testing a known large case that might overflow
        try {
            // Example: Large values that would exceed Integer.MAX_VALUE
            // 2147483647 is Integer.MAX_VALUE. 
            // If a=2147483647, b=2, gcd=1. (2147483647 + 1) * 2 = 2147483648 * 2 -> overflows.
            MathUtils.lcm(Integer.MAX_VALUE, 2);
        } catch (ArithmeticException e) {
            assertEquals("overflow: lcm is 2^31", e.getMessage());
        } catch (Exception e) {
            // If mulAndCheck throws exception directly, that's also acceptable behavior for overflow
        }
    }

    @Test
    public void testLcmSmallNumbers() {
        assertEquals(2, MathUtils.lcm(1, 2));
        assertEquals(6, MathUtils.lcm(2, 3));
        assertEquals(20, MathUtils.lcm(4, 5));
    }
}
